effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.rgb;
    vec3 acc = c;
    for(int i=0;i<12;i++){
        float a = float(i)/12.0*6.28318;
        vec2 o = vec2(cos(a),sin(a))*radius;
        acc += texture2DCv(inputImg.texture, acScreenNorm+o).rgb;
    }
    acc /= 13.0;
    vec3 outc = 1.0 - (1.0-c)*(1.0-acc*glow);
    gl_FragColor = vec4(outc, src.a);
}
